AP4_Result ReadVisualSampleEntry(AP4_ByteStream& stream) {
    AP4_Result result = ReadSampleEntry(stream);
    if (AP4_SUCCEEDED(result)) {
        // Read predefined values
        AP4_UI32 predefined;
        result = stream.ReadUI32(predefined);
        if (AP4_FAILED(result)) return result;

        // Read width and height
        AP4_UI16 width, height;
        result = stream.ReadUI16(width);
        if (AP4_FAILED(result)) return result;
        result = stream.ReadUI16(height);
        if (AP4_FAILED(result)) return result;

        // Read horizontal and vertical resolutions
        AP4_UI32 h_res, v_res;
        result = stream.ReadUI32(h_res);
        if (AP4_FAILED(result)) return result;
        result = stream.ReadUI32(v_res);
        if (AP4_FAILED(result)) return result;

        // Read frame count
        AP4_UI16 frame_count;
        result = stream.ReadUI16(frame_count);
        if (AP4_FAILED(result)) return result;

        // Read compressor name (32 bytes)
        char compressor_name[33] = {0};
        result = stream.ReadData((AP4_Byte*)compressor_name, 32);
        if (AP4_FAILED(result)) return result;
        compressor_name[32] = '\0';  // Ensure null termination

        // Read bits per sample
        AP4_UI16 bits_per_sample;
        result = stream.ReadUI16(bits_per_sample);
        if (AP4_FAILED(result)) return result;

        // Read color space
        AP4_UI32 color_space[3];
        result = stream.ReadUI32(color_space[0]);
        if (AP4_FAILED(result)) return result;
        result = stream.ReadUI32(color_space[1]);
        if (AP4_FAILED(result)) return result;
        result = stream.ReadUI32(color_space[2]);
        if (AP4_FAILED(result)) return result;

        // Read additional depth and predefined values
        AP4_UI16 depth;
        AP4_UI16 additional_predefined;
        result = stream.ReadUI16(depth);
        if (AP4_FAILED(result)) return result;
        result = stream.ReadUI16(additional_predefined);
        if (AP4_FAILED(result)) return result;
    }

    return result;
}

