AP4_Result ReadVisualSampleEntry(AP4_ByteStream& stream) {
    AP4_Result result = ReadSampleEntry(stream);
    if (AP4_FAILED(result)) return result;

    AP4_UI32 predefined1;
    AP4_UI16 width;
    AP4_UI16 height;
    AP4_UI32 resolution;
    AP4_UI16 frame_count;
    AP4_UI32 compressor_name_length;
    AP4_UI16 depth;
    AP4_UI16 predefined2;

    stream.ReadUI32(predefined1);
    stream.ReadUI16(width);
    stream.ReadUI16(height);
    stream.ReadUI32(resolution);
    stream.ReadUI16(frame_count);

    stream.ReadUI32(compressor_name_length);
    AP4_UI08* compressor_name = new AP4_UI08[compressor_name_length];
    stream.ReadData(compressor_name, compressor_name_length);
    compressor_name[compressor_name_length - 1] = '\0';  // Ensure null-termination

    stream.ReadUI16(depth);
    stream.ReadUI16(predefined2);

    delete[] compressor_name;
    return AP4_SUCCESS;
}

